{"code":"import math


def _prime_pi(n):
    # number of primes <= n, Lucy_Hedgehog O(n^{3/4}), memory O(sqrt n)
    if n < 2:
        return 0
    r = math.isqrt(n)
    V = [n // i for i in range(1, r + 1)]
    V += list(range(V[-1] - 1, 0, -1))
    S = {v: v - 1 for v in V}
    for p in range(2, r + 1):
        if S[p] > S[p - 1]:
            sp = S[p - 1]
            p2 = p * p
            for v in V:
                if v < p2:
                    break
                S[v] -= S[v // p] - sp
    return S[n]


def solve(*args, **kwargs):
    if args:
