    if isinstance(n, str):
        n = int(n.strip())
    elif isinstance(n, float):
        n = int(n)
    else:
        n = int(n)
    if n < 3:
        return 0
    m = n - 1
    if m <= 10 ** 7:
        sieve = bytearray([1]) * (m + 1)
        sieve[0] = 0
        sieve[1] = 0
        i = 2
        while i * i <= m:
            if sieve[i]:
                sieve[i * i::i] = bytearray(len(range(i * i, m + 1, i)))
            i += 1
        return sum(sieve)
    return _prime_pi(m)
