from collections import defaultdict


def solve(*args, **kwargs):
    if len(args) >= 2:
        n, edges = args[0], args[1]
    elif len(args) == 1:
        n = args[0]
        edges = kwargs.get('edges', kwargs.get('edge_list', kwargs.get('e', [])))
    else:
        n = kwargs.get('n', 0)
        edges = kwargs.get('edges', kwargs.get('edge_list', kwargs.get('e', [])))
    n = int(n)
    if edges is None:
        edges = []
    adj = defaultdict(list)
    indeg = [0] * n
    for e in edges:
        a, b = e[0], e[1]
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    res = []
    while heap:
        u = heapq.heappop(heap)
        res.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(res) != n:
        return []
    return res
